const RAW: Lab[] = [
  { id: 'quake', name: '地震', hook: '一次真实的地震：发生、预警、看穿地球', desc: '以 2008 年汶川地震为主线，在龙门山沙盘上剖开地面看断层错动和震源，比较 8 级和 7 级地震的能量和烈度；在河谷小镇看纵波和横波先颠后晃，算出预警能为各座城市抢到几秒，用三个台站的圆找到震中；再切开地球，看地震波怎样穿过各圈层、横波为什么到外核就消失；最后比一比三栋楼谁和地震共振，在全球找出两条地震带。', pts: ['震级与烈度', '纵波与横波', '地震预警', '地球的圈层'], s: 'geo', grade: '高中', book: '必修一', n: 7, href: '/labs/quake/index.html', issue: 42 },
  { id: 'float', name: '浮力', hook: '为什么钢铁做的船能浮在水上', desc: '在一座造船厂里做实验：用吊车把船锚放进港池，看吊秤读数少了多少；接住溢出来的水，称一称有多重。最后弄懂一块会沉的钢铁怎样变成能浮的船，再去太空看浮力为什么消失。', pts: ['称重法测浮力', '阿基米德原理', '浮沉条件'], s: 'phys', grade: '初中', book: '八年级下册', n: 7, href: '/labs/float/index.html' },
  { id: 'pressure', name: '压强', hook: '大坝为什么要做成上窄下宽', desc: '在一座水电站里做实验：把混凝土块压在沙地上、让卡车开上软土，弄懂压强；把探头伸进水库，量出越深压强越大；再自己开船闸、做托里拆利实验、吹风洞。所有的课都在同一个大场景里，换课时镜头飞过去。', pts: ['压强 p = F/S', '液体压强 p = ρgh', '大气压与流速'], s: 'phys', grade: '初中', book: '八年级下册', n: 7, href: '/labs/pressure/index.html' },
  { id: 'lens', name: '凸透镜成像', hook: '蜡烛离透镜多远，决定了像是什么样', desc: '在一间光学暗室里看光怎样在水面拐弯、凸透镜怎样把光聚到一点；自己移动蜡烛和光屏，记下四组数据找出成像的规律，再用三条光线把像画出来，最后弄懂照相机、眼镜和望远镜。', pts: ['成像规律', '焦距', '实像与虚像'], s: 'phys', grade: '初中', book: '八年级上册', n: 7, issue: 5, href: '/labs/lens/index.html' },
  { id: 'battery', name: '原电池', hook: '化学反应怎样点亮一盏灯', desc: '把锌片和铜片插进稀硫酸，连上导线，灯亮了。一步步看电子从哪里出发、离子往哪里走；少一个条件行不行，换一对电极会怎样；再剖开一节干电池，给燃料电池通上氢气和氧气。', pts: ['氧化还原', '电极反应', '化学电源'], s: 'chem', grade: '高中', book: '必修二', n: 7, href: '/labs/battery/index.html', issue: 24 },
  { id: 'pyth', name: '勾股定理', hook: '把两个正方形拼进第三个', desc: '亲手把两个小正方形拼进斜边上的大正方形，再看赵爽的弦图怎样用面积证明它。', pts: ['拼图证明', '赵爽弦图', '勾股数'], vb: '0 -4 320 204', s: 'math', grade: '初中', book: '八年级下册', n: 5, issue: 43 },
  { id: 'ammonia', name: '合成氨工厂', hook: '一座化肥厂里的化学平衡', desc: '走进一座化肥厂。温度高了反应快但产率低，压强大了产率高但设备贵。自己调条件，看一天能多产多少吨氨，理解工业上为什么这样选。', pts: ['化学平衡', '反应速率', '工业条件的选择'], vb: '0 0 320 190', s: 'chem', grade: '高中', book: '选必一', n: 7, issue: 25 },
  { id: 'blood', name: '血液循环', hook: '跟着一团血走一圈，看它在哪里换了气', desc: '在一座科学馆的人体展厅里，先让一管血静置分层、认出三种血细胞，剖开三段血管比管壁；再剖开一颗心脏，认四个腔和两种瓣膜，看心房心室怎样轮流收缩、瓣膜怎样让血只往一个方向流；跟着一团血走完体循环和肺循环，到肺泡和组织里看氧和二氧化碳往哪边走，最后量一次血压、数一次脉搏。', pts: ['心脏的结构', '体循环', '肺循环'], n: 7, href: '/labs/blood/index.html', s: 'bio', grade: '初中', book: '七年级下册', issue: 31 },
  { id: 'leaf', name: '光合作用和呼吸作用', hook: '一片叶子怎样把阳光变成养分', desc: '在一座蔬菜大棚里把课本上的经典实验亲手做一遍：遮住半片叶子看淀粉在哪里生成，数金鱼藻冒出的氧气泡，比较萌发和煮熟的种子，再看大棚里一昼夜的二氧化碳怎么变。', pts: ['光合作用的条件和产物', '叶片的结构', '呼吸作用和增产'], s: 'bio', grade: '初中', book: '七年级上册', n: 7, href: '/labs/leaf/index.html', issue: 27 },
  { id: 'orbit', name: '地球的运动', hook: '为什么夏天的白天更长', desc: '让地球自己转、绕着太阳转。盯住北京，看它什么时候天亮、夏天的白天有多长、正午旗杆的影子有多短，再弄懂五带是怎么分出来的。所有的课都在同一个太阳和地球的大场景里。', pts: ['自转和公转', '太阳直射点', '昼夜长短和五带'], s: 'geo', grade: '初中', book: '七年级上册', n: 7, featured: true, trail: '从昼夜到四季，一路看到五带', lessons: ['自转', '时差', '公转', '直射点', '昼长', '影长', '五带'], href: '/labs/orbit/index.html', issue: 36 },
  // ---------- 以下是总规划表里还没有做的实验室：没有封面线稿，卡片上用占位图，点开是它的认领议题 ----------
  { id: 'motion', name: '机械运动', hook: '动还是没动，要看跟谁比', desc: '在一座高铁站里量车票、读停表；换三个参照物，看同一列车是动是静；让三列车各跑 10 秒比快慢；再用一段斜坡和一辆小车，亲手测一次平均速度。', n: 7, href: '/labs/motion/index.html', pts: ['长度和时间的测量', '速度', '参照物'], s: 'phys', grade: '初中', book: '八年级上册', issue: 1 },
  { id: 'sound', name: '声现象', hook: '声音是振动出来的，没有空气就传不过来', desc: '在一座音乐厅的舞台上敲音叉、敲鼓，看贴着叉臂的乒乓球被弹开；把闹钟罩进玻璃罩抽走空气，铃声越来越小；拍一下手等回声，算出墙有多远；再用钢尺、鼓和三种乐器分清音调、响度、音色，最后到后台把风机的噪声挡住。', n: 7, href: '/labs/sound/index.html', pts: ['声音的产生和传播', '音调 响度 音色', '噪声'], s: 'phys', grade: '初中', book: '八年级上册', issue: 2 },
  { id: 'phase', name: '物态变化', hook: '水烧开以后再加热，温度为什么不升了', desc: '在山脚的一座气象站里学用温度计；给海波和石蜡加热，画出两条不一样的熔化图线；比一比两滴水谁先干；把水烧开，看气泡和温度怎么变；再看“白气”、碘蒸气和干冰，最后走到屋外，把冰凌、露水、霜和雪一个个对上号。', n: 7, href: '/labs/phase/index.html', pts: ['熔化和凝固', '汽化和液化', '升华和凝华'], s: 'phys', grade: '初中', book: '八年级上册', issue: 3 },
  { id: 'mirror', name: '光的反射和平面镜', hook: '镜子里的像和你一样大、一样远', desc: '在一间光学暗室里用小孔成像看光走直线；让激光射到镜面上，量出反射角总等于入射角；隔着玻璃板移动另一支蜡烛，找到像的位置；再画出潜望镜的光路，算一算照全身要多高的镜子，看凹面镜和凸面镜各把光怎么样。', n: 7, href: '/labs/mirror/index.html', pts: ['光的直线传播', '反射定律', '平面镜成像'], s: 'phys', grade: '初中', book: '八年级上册', issue: 4 },
  { id: 'density', name: '质量与密度', hook: '一样大的铝和铜，为什么不一样重', desc: '在冶炼厂的化验室里学用托盘天平：调平、左物右码、从大到小试砝码、移游码；用量筒和排水法量体积；称几块铝和铜，在图上连出两条直线，得到密度；再测一块石头和一杯盐水，到料场认出一块金属、算出大铝锭有多重。', n: 7, href: '/labs/density/index.html', pts: ['质量', '密度', '测量物质的密度'], s: 'phys', grade: '初中', book: '八年级上册', issue: 6 },
  { id: 'force', name: '力和运动', hook: '没有阻力，小车会一直滑下去', desc: '在冰壶道上推冰壶，看力的大小、方向、作用点各管什么；在器材室里用弹簧测力计称钩码，画出重力和质量的图线；让小车在毛巾、棉布、木板上各滑一次，推想没有阻力会怎样；再看惯性、二力平衡，量一量滑动摩擦力跟什么有关。', n: 7, href: '/labs/force/index.html', pts: ['牛顿第一定律', '二力平衡', '摩擦力'], s: 'phys', grade: '初中', book: '八年级下册', issue: 7 },
  { id: 'energy', name: '功和机械能', hook: '功、功率', desc: '功、功率；动能和势能怎样转化。场景设想：游乐园：过山车、蹦极。', pts: ['功和功率', '动能和势能', '机械能守恒'], s: 'phys', grade: '初中', book: '八年级下册', issue: 8 },
  { id: 'machine', name: '简单机械', hook: '一根撬棍，凭什么能撬动比自己重得多的石头', desc: '在一处建筑工地上用撬棍撬石头，画出动力臂和阻力臂；在工棚的实验台上调平杠杆尺、挂钩码，找出杠杆的平衡条件；再用测力计斜着拉，比一比手推车、铁锹和天平，用定滑轮、动滑轮和滑轮组把钩码提起来，测出机械效率，最后看塔吊怎样靠配重保持平衡。', n: 7, href: '/labs/machine/index.html', pts: ['杠杆', '滑轮', '机械效率'], s: 'phys', grade: '初中', book: '八年级下册', issue: 9 },
  { id: 'heat', name: '内能和热机', hook: '汽车是怎样被汽油推着走的', desc: '在一座汽车发动机厂里：往冷水和热水里滴红墨水看分子运动，压紧两块铅柱挂钩码，用引火仪点燃棉花，加热水和食用油比较比热容，算发动机冷却液吸了多少热；剖开一台汽油机看吸气、压缩、做功、排气四个冲程，算热值和热机效率；最后到总装线看四个缸怎样轮流点火，再看柴油机怎样压燃。', pts: ['分子热运动', '比热容', '热机'], n: 7, href: '/labs/heat/index.html', s: 'phys', grade: '初中', book: '九年级', issue: 10 },
  { id: 'circuit', name: '电路', hook: '两盏灯，拧下一盏，另一盏还亮不亮', desc: '在一栋正在做水电改造的房子里，用电池盒、小灯泡和开关连出通路、断路和短路；把两盏灯串起来、再并起来，拧下一盏看另一盏；学会接电流表和电压表、选量程、读数，找出串联和并联电路里电流和电压的规律；比一比几根金属丝的电阻，用滑动变阻器调亮度，最后看楼梯灯的双控开关和墙上的插座是怎样接的。', pts: ['串联和并联', '电流和电压', '电阻'], n: 7, href: '/labs/circuit/index.html', s: 'phys', grade: '初中', book: '九年级', issue: 11 },
  { id: 'ohm', name: '欧姆定律', hook: '电压加倍，电流也加倍吗', desc: '在一间电子元件检测车间里，用电源、电流表、电压表和滑动变阻器，先保持电阻不变改电压、再保持电压不变换电阻，把数据点画成图像，找出欧姆定律；用伏安法测定值电阻和小灯泡的电阻，比一比串联、并联后的总电阻；再看人体电阻和安全用电，最后给一批色环电阻做质检，拆开油量表看它怎样用电阻测油量。', pts: ['欧姆定律', '伏安法测电阻', '串并联电路的规律'], n: 7, href: '/labs/ohm/index.html', s: 'phys', grade: '初中', book: '九年级', issue: 12 },
  { id: 'power', name: '电功率和生活用电', hook: '电费是怎么算出来的', desc: '在一栋住宅楼和小区配电房里：读楼道电能表算一个月用了多少电，数指示灯闪烁测电水壶的功率，调小灯泡电压比较额定功率和实际功率，用串联的两瓶煤油验证焦耳定律；剖开墙看火线、零线、地线和并联的用电器，用试电笔辨火线、看漏电保护器跳闸，再找出电流过大的两个原因。', pts: ['电能和电功率', '焦耳定律', '安全用电'], n: 7, href: '/labs/power/index.html', s: 'phys', grade: '初中', book: '九年级', issue: 13 },
  { id: 'magnet', name: '电与磁', hook: '风车是怎样把风变成电的', desc: '在风电场山脚的运维站里：用磁体吸铁钉、看磁极相斥相吸，撒铁屑、摆小磁针画出磁感线，做奥斯特实验和通电螺线管，比较电磁铁的磁性强弱；让通电铜棒在磁场里滚起来、再让铜棒切割磁感线产生电流，摇一摇发电机；最后登上风机，剖开机舱看齿轮箱和发电机，再看电磁继电器和扬声器。', pts: ['磁场', '电生磁', '电动机和发电机'], n: 7, href: '/labs/magnet/index.html', s: 'phys', grade: '初中', book: '九年级', issue: 14 },
  { id: 'projectile', name: '抛体运动', hook: '一个运动拆成两个方向来看', desc: '运动的合成与分解；平抛的规律；初速度、角度、高度怎样一起决定落点。场景设想：山地消防：水炮和空投。', pts: ['运动的合成与分解', '平抛运动', '落点和射程'], s: 'phys', grade: '高中', book: '必修第二册', issue: 61 },
  { id: 'gravity', name: '万有引力与航天', hook: '速度差一点，轨道就从圆变成椭圆', desc: '开普勒三定律；第一宇宙速度；卫星怎样变轨；同步卫星。场景设想：从发射场到轨道。', pts: ['开普勒定律', '宇宙速度', '卫星变轨'], s: 'phys', grade: '高中', book: '必修第二册', issue: 62 },
  { id: 'momentum', name: '动量和碰撞', hook: '动量守恒了，动能却不一定', desc: '动量和冲量；动量守恒；弹性碰撞和非弹性碰撞的区别；反冲。场景设想：冰球场和火箭试车台。', pts: ['动量和冲量', '动量守恒', '碰撞和反冲'], s: 'phys', grade: '高中', book: '选择性必修第一册', issue: 63 },
  { id: 'wave', name: '机械振动和机械波', hook: '一上一下的振动怎样传成一道波', desc: '单摆和弹簧振子；共振；波的叠加、干涉、衍射；多普勒效应。场景设想：海港和防波堤。', pts: ['简谐运动', '共振', '干涉和衍射'], s: 'phys', grade: '高中', book: '选择性必修第一册', issue: 64 },
  { id: 'efield', name: '静电场', hook: '看不见的电场，怎样把一滴墨打到该去的地方', desc: '电场线和等势面；带电粒子在电场里的加速和偏转；电容器。场景设想：喷墨打印机工厂。', pts: ['电场强度和电势', '带电粒子的偏转', '电容器'], s: 'phys', grade: '高中', book: '必修第三册', issue: 65 },
  { id: 'bfield', name: '带电粒子在磁场中', hook: '磁场不做功，却能让粒子转弯', desc: '洛伦兹力；圆周运动的半径和周期；速度选择器、质谱仪、回旋加速器。场景设想：粒子加速器实验室。', pts: ['洛伦兹力', '圆周运动', '质谱仪和回旋加速器'], s: 'phys', grade: '高中', book: '选择性必修第二册', issue: 66 },
  { id: 'induction', name: '电磁感应和电网', hook: '电是怎样从发电厂送到你家的', desc: '楞次定律和法拉第电磁感应定律；发电机；变压器；为什么要高压输电。场景设想：从发电厂到城市的输电线。', pts: ['电磁感应', '交变电流和变压器', '远距离输电'], s: 'phys', grade: '高中', book: '选择性必修第二册', issue: 67 },
  { id: 'light', name: '光的波动性和光电效应', hook: '光有时像波，有时像一颗颗粒子', desc: '双缝干涉的条纹间距；薄膜干涉；光电效应的截止频率和遏止电压。场景设想：光学实验室。', pts: ['光的干涉和衍射', '光电效应', '波粒二象性'], s: 'phys', grade: '高中', book: '选择性必修第一册', issue: 68 },
  { id: 'air', name: '空气和氧气', hook: '空气里有什么', desc: '空气里有什么；氧气的性质和制法。场景设想：空气分离厂。', pts: ['空气的成分', '氧气的性质', '氧气的制取'], s: 'chem', grade: '初中', book: '九年级上册', issue: 15 },
  { id: 'atom', name: '分子和原子', hook: '分子在运动、有间隔', desc: '分子在运动、有间隔；原子的结构；元素。场景设想：从一滴水一路放大到原子。', pts: ['分子和原子', '原子的结构', '元素'], s: 'chem', grade: '初中', book: '九年级上册', issue: 16 },
  { id: 'water', name: '水的净化和组成', hook: '一杯浑浊的河水，怎样变成能喝的自来水', desc: '在一座自来水厂里，先从河里取一杯水，看看里面有什么；在化验室加明矾沉淀、用滤纸过滤、用活性炭吸附，再沿着厂区从取水口走到清水池，看水一步步变清、被消毒；用肥皂水分辨硬水和软水，煮沸、蒸馏；最后用电解器把水分解，正极得到氧气、负极得到氢气，说明水由氢、氧两种元素组成。', pts: ['水的净化', '电解水', '硬水和软水'], n: 7, href: '/labs/water/index.html', s: 'chem', grade: '初中', book: '九年级上册', issue: 17 },
  { id: 'mass', name: '质量守恒定律', hook: '东西烧掉了，质量去哪了', desc: '在一座纯碱化工厂的化验室里，用托盘天平称红磷燃烧、铁和硫酸铜反应前后的质量，再看敞口烧杯和镁条燃烧为什么“不守恒”；电解水、看分子拆开再重组，原子的种类和数目不变；到反应车间读化学方程式的意义，在中控室一步步配平方程式；最后到石灰窑按方程式算原料、过秤对账。', pts: ['质量守恒定律', '化学方程式', '化学计算'], n: 7, href: '/labs/mass/index.html', s: 'chem', grade: '初中', book: '九年级上册', issue: 18 },
  { id: 'carbon', name: '碳和二氧化碳', hook: '汽水一打开，为什么会冒泡', desc: '在一座汽水厂和旁边的玻璃温室里，先认金刚石、石墨和 C60 的结构；在化验室用大理石和稀盐酸制取二氧化碳，验满、倒进阶梯蜡烛、灌进软塑料瓶，看它和水、石灰水怎样反应；到灌装车间给汽水加压充气、开瓶看冒泡；用一氧化碳还原氧化铜并处理尾气；在温室里补二氧化碳看番茄的光合作用，理解碳循环；最后看干冰怎样升华。', pts: ['二氧化碳的制取', '一氧化碳', '碳循环'], n: 7, href: '/labs/carbon/index.html', s: 'chem', grade: '初中', book: '九年级上册', issue: 19 },
  { id: 'fire', name: '燃烧和灭火', hook: '为什么热水里的白磷，通上氧气就能燃烧', desc: '在一座消防训练基地里，先在实验厅把课本上的经典实验做一遍：加热木条和石块、用烧杯罩住蜡烛、铜片上的白磷和红磷、热水里通氧气，找出燃烧的三个条件；再到训练场用燃烧箱验证火三角，按原理选灭火办法，为不同的火选对灭火器，看面粉怎样引起粉尘爆炸，最后割出隔离带、低姿逃生、用水炮扑灭训练塔里的火。', pts: ['燃烧的条件', '灭火的原理', '燃料'], n: 7, href: '/labs/fire/index.html', s: 'chem', grade: '初中', book: '九年级上册', issue: 20 },
  { id: 'metal', name: '金属和炼铁', hook: '为什么铁会生锈、金子不会', desc: '在一座钢铁厂的化验楼里：比较金属的导电、导热和硬度，把镁、铝、铜、金放在火上烧，把四种金属放进稀盐酸看谁冒泡快，让铁丝换出铜、铜丝换出银，排出金属活动性顺序；再用一氧化碳还原氧化铁，到高炉看出铁，用三支试管找铁生锈的条件，最后进轧钢车间把钢坯轧成钢板。', pts: ['金属活动性顺序', '铁的冶炼', '锈蚀和防护'], n: 7, href: '/labs/metal/index.html', s: 'chem', grade: '初中', book: '九年级下册', issue: 21 },
  { id: 'solution', name: '溶液', hook: '海水是怎样变成盐的', desc: '在一座盐湖边的盐场化验室里：把蔗糖、泥沙、植物油放进水里分辨溶液、悬浊液和乳浊液，比较硝酸铵、氢氧化钠、氯化钠溶解时的温度变化，一勺勺加盐找饱和，测出溶解度并在白板上画溶解度曲线；用蒸发和降温两种办法让晶体析出，配一瓶 6% 的氯化钠溶液；最后到盐田看引卤、晒卤、收盐，冬天到湖边看碱。', pts: ['溶解和结晶', '溶解度曲线', '溶质的质量分数'], n: 7, href: '/labs/solution/index.html', s: 'chem', grade: '初中', book: '九年级下册', issue: 22 },
  { id: 'acid', name: '酸、碱和中和', hook: '酸和碱的性质', desc: '酸和碱的性质；pH；中和反应。场景设想：污水处理厂。', pts: ['酸和碱的性质', 'pH', '中和反应'], s: 'chem', grade: '初中', book: '九年级下册', issue: 23 },
  { id: 'electrolysis', name: '电解和金属防护', hook: '通上电，让本来不会发生的反应发生', desc: '电解池和原电池有什么不同；离子的放电顺序；电解精炼、电镀；金属的电化学防护。场景设想：氯碱厂和电镀车间。', pts: ['电解原理', '电解的应用', '金属的腐蚀与防护'], s: 'chem', grade: '高中', book: '选择性必修 1', issue: 69 },
  { id: 'ionic', name: '水溶液里的离子平衡', hook: '滴到哪一滴，溶液突然变了性', desc: '弱电解质的电离；水的电离和 pH；中和滴定曲线；盐类水解；沉淀溶解平衡。场景设想：水质检测中心。', pts: ['电离平衡和 pH', '中和滴定', '水解和沉淀溶解平衡'], s: 'chem', grade: '高中', book: '选择性必修 1', issue: 70 },
  { id: 'sulfuric', name: '接触法制硫酸', hook: '反应要快，又要彻底，工厂怎么选条件', desc: '硫怎样一步步变成硫酸；速率和平衡怎样取舍；工业上为什么选这个温度和压强；尾气怎样处理。场景设想：硫酸厂。', pts: ['硫及其化合物', '速率和平衡的取舍', '工业条件的选择'], s: 'chem', grade: '高中', book: '必修第二册', issue: 71 },
  { id: 'crystal', name: '分子的形状和晶体', hook: '几对电子，决定了分子长什么样', desc: '价层电子对互斥模型；杂化轨道；晶胞里怎样数粒子；四类晶体的区别。场景设想：晶体实验室。', pts: ['分子的空间结构', '晶胞', '晶体的类型'], s: 'chem', grade: '高中', book: '选择性必修 2', issue: 72 },
  { id: 'petro', name: '从石油到塑料', hook: '一桶原油怎样变成汽油、酒精和塑料', desc: '石油的分馏、裂化、裂解；官能团怎样一步步转化；加聚反应。场景设想：炼油厂。', pts: ['石油的炼制', '官能团的转化', '加聚反应'], s: 'chem', grade: '高中', book: '必修第二册', issue: 73 },
  { id: 'cells', name: '细胞', hook: '怎样才能看见细胞，看见了什么', desc: '在一间生物实验室里学会用显微镜：对光、调焦、把偏掉的物像移回来；亲手做一张洋葱表皮的临时装片；再把放大的植物细胞和动物细胞一个结构一个结构地点亮，看一个细胞怎样分裂成两个。', n: 7, href: '/labs/cells/index.html', pts: ['显微镜', '细胞的结构', '细胞分裂'], s: 'bio', grade: '初中', book: '七年级上册', issue: 26 },
  { id: 'plant', name: '植物的一生', hook: '一粒种子里，已经有一棵小植物', desc: '在一块试验田边剥开菜豆和玉米的种子，找到胚；用四个瓶子做对照，找出种子萌发要的条件；隔着玻璃看胚根先钻出来、子叶被拉出土；推近看根尖的四个区；再到桃树下认一朵花的各部分，看花粉管怎样把精子送到胚珠，子房长成一只桃。', n: 7, href: '/labs/plant/index.html', pts: ['种子的萌发', '根的生长', '开花和结果'], s: 'bio', grade: '初中', book: '七年级上册', issue: 28 },
  { id: 'digest', name: '消化和吸收', hook: '一口馒头去了哪里', desc: '在一座人体营养展厅里：给馒头滴碘液、压花生、揉洗面团，找出食物里的营养；沿消化道认器官和消化腺，做唾液消化淀粉的经典实验，剖开胃看蠕动，在十二指肠里看胆汁乳化脂肪、消化液把营养拆成小分子；剖开小肠看皱襞和绒毛怎样吸收；最后搭一份平衡的午餐，跟着一口馒头走完消化道。', pts: ['消化系统', '营养物质', '吸收'], n: 7, href: '/labs/digest/index.html', s: 'bio', grade: '初中', book: '七年级下册', issue: 29 },
  { id: 'breath', name: '呼吸', hook: '吸一口气时，胸腔里发生了什么', desc: '在科学馆的呼吸展厅里，跟着一口空气走过鼻、咽、喉、气管、支气管，看它怎样被清洁、温暖、湿润；一级级放大到肺泡；看肋间肌和膈怎样让胸廓变大变小，用钟罩模型拉下橡皮膜让气球鼓起来；读出吸气、呼气时肺内的气压，看肺泡里氧和二氧化碳往哪边走；比一比吸入和呼出的气体，最后量胸围差、了解海姆立克急救。', pts: ['呼吸运动', '肺泡', '气体交换'], n: 7, href: '/labs/breath/index.html', s: 'bio', grade: '初中', book: '七年级下册', issue: 30 },
  { id: 'nerve', name: '神经调节', hook: '手碰到烫杯子为什么先缩回来再觉得烫', desc: '在一座人体神经系统展馆里：认脑、脊髓和神经，看神经冲动怎样沿一个神经元走；手指碰到烫杯子，跟着冲动走完反射弧，再剪断传入或传出神经看会怎样；叩膝盖看膝跳反射，比较吃梅、看梅、说梅；剖开眼球和耳朵，看光和声音怎样变成视觉和听觉；最后认大脑、小脑、脑干，接一次落下的尺子测反应时间。', pts: ['反射弧', '神经系统', '眼和耳'], n: 7, href: '/labs/nerve/index.html', s: 'bio', grade: '初中', book: '七年级下册', issue: 32 },
  { id: 'gene', name: '遗传和变异', hook: '基因在亲子代之间怎样传递', desc: '基因在亲子代之间怎样传递；显性和隐性；性别决定。场景设想：一座豌豆试验园。', pts: ['基因和性状', '显性和隐性', '性别决定'], s: 'bio', grade: '初中', book: '八年级下册', issue: 33 },
  { id: 'eco', name: '生态系统', hook: '狼少了，草原为什么反而会变差', desc: '在一片草原和小湖边：用实验盒看光对鼠妇分布的影响，认生产者、消费者、分解者和非生物部分；连出草、兔、狐的食物链，数一数食物网里有几条链，看太阳能怎样一级级往上传、每级只剩一小部分；跟一个碳原子走一圈，看农药怎样沿食物链越积越多；再比较捕杀狼以后兔和草的变化，最后看看湖泊、森林、农田和一只生态瓶。', pts: ['食物链和食物网', '物质和能量', '生态平衡'], n: 7, href: '/labs/eco/index.html', s: 'bio', grade: '初中', book: '七年级上册', issue: 34 },
  { id: 'chloroplast', name: '光反应和暗反应', hook: '突然停了光，叶绿体里先乱的是哪一步', desc: '光反应和暗反应各在哪里进行、各做什么；两个阶段怎样联系；条件突变时各物质怎样变化。场景设想：走进一个叶绿体。', pts: ['光反应', '暗反应', '条件变化的影响'], s: 'bio', grade: '高中', book: '必修 1', issue: 74 },
  { id: 'expression', name: '基因的表达', hook: '四种碱基怎样写出一个蛋白质', desc: 'DNA 的复制；转录和翻译；密码子；碱基改变对蛋白质的影响。场景设想：从细胞核到核糖体。', pts: ['DNA 的复制', '转录和翻译', '基因突变的影响'], s: 'bio', grade: '高中', book: '必修 2', issue: 75 },
  { id: 'meiosis', name: '减数分裂和遗传规律', hook: '染色体怎样分，性状就怎样传', desc: '减数分裂中染色体的行为；分离定律和自由组合定律；伴性遗传；概率的计算。场景设想：果蝇实验室。', pts: ['减数分裂', '孟德尔定律', '伴性遗传'], s: 'bio', grade: '高中', book: '必修 2', issue: 76 },
  { id: 'neuron', name: '兴奋的传导和传递', hook: '一个信号怎样从指尖跑到大脑', desc: '静息电位和动作电位；兴奋在神经纤维上的传导；突触怎样传递；药物作用在哪一步。场景设想：沿着一根神经纤维。', pts: ['静息电位和动作电位', '兴奋的传导', '突触传递'], s: 'bio', grade: '高中', book: '选择性必修 1', issue: 77 },
  { id: 'population', name: '种群和生态系统', hook: '岛上的兔子为什么不会无限多下去', desc: '种群的 J 形和 S 形增长；捕食者和猎物的数量波动；能量流动逐级递减。场景设想：一座孤岛。', pts: ['种群数量的变化', '种间关系', '能量流动'], s: 'bio', grade: '高中', book: '选择性必修 2', issue: 78 },
  { id: 'globe', name: '地球和经纬网', hook: '经线、纬线', desc: '经线、纬线；用经纬度定位；半球的划分。场景设想：一艘远洋科考船和一只大地球仪。', pts: ['经线和纬线', '经纬度定位', '东西半球'], s: 'geo', grade: '初中', book: '七年级上册', issue: 35 },
  { id: 'contour', name: '等高线地形图', hook: '一张平面图怎么看出山的高低', desc: '在一块切开的山地沙盘上量海拔、算相对高度，用水平面一层层切山画出等高线，再把山压平成地图；沿缓坡和陡坡各爬一次比较疏密，认出山峰、盆地、山脊、山谷、鞍部和陡崖，看雨水怎样顺山谷汇成河；最后给地图分层设色、画地形剖面，用等高线选翻山路线、坝址和看日出的地方。', pts: ['等高线', '地形部位', '地形剖面'], n: 7, href: '/labs/contour/index.html', s: 'geo', grade: '初中', book: '七年级上册', issue: 37 },
  { id: 'plate', name: '板块运动', hook: '大西洋两岸为什么能拼在一起', desc: '沿着一条从太平洋、安第斯山、大西洋中脊、东非大裂谷到喜马拉雅的地球切片，把南美洲和非洲拼回去，看大陆漂移的证据；看洋中脊怎样生出新的洋底、两侧岩石的年龄怎样对称；认出六大板块，看板块张裂成裂谷和海、大陆相撞隆起喜马拉雅、大洋板块俯冲形成海沟和火山；最后在地球上标出火山和地震，找出两条火山地震带。', pts: ['大陆漂移', '板块构造', '火山和地震带'], n: 7, href: '/labs/plate/index.html', s: 'geo', grade: '初中', book: '七年级上册', issue: 38 },
  { id: 'climate', name: '天气和气候', hook: '为什么山这边下雨、那边干旱', desc: '在一座山脚的气象站里：读天气预报分清天气和气候，打开百叶箱一天读四次温度、算日平均气温，用雨量器和量杯量降水；在大地球仪上看气温和降水怎样随纬度、海陆分布，翻过一座大山比较迎风坡和背风坡；画一张气温曲线和降水柱状图，最后找出几座城市的气候主要受什么影响。', pts: ['气温', '降水', '气候类型'], n: 7, href: '/labs/climate/index.html', s: 'geo', grade: '初中', book: '七年级上册', issue: 39 },
  { id: 'watercycle', name: '水循环', hook: '跟着一滴水走遍一个流域', desc: '一块从海洋到雪山的地块：一个环节一个环节地打开水循环，比较雨落在林地和水泥地上的不同，修一座水库，给城市下一场暴雨，最后算一算全球一年的水账。', n: 7, href: '/labs/watercycle/index.html', pts: ['水循环的环节', '陆地水体', '人类活动的影响'], s: 'geo', grade: '高中', book: '必修第一册', issue: 40 },
  { id: 'wind', name: '热力环流和风', hook: '大气怎样受热', desc: '大气怎样受热；热力环流；海陆风、山谷风。场景设想：一座海滨城市。', pts: ['大气受热过程', '热力环流', '海陆风'], s: 'geo', grade: '高中', book: '必修第一册', issue: 41 },
  { id: 'circulation', name: '大气环流', hook: '风带为什么会跟着太阳南北搬家', desc: '三圈环流；气压带和风带的季节移动；季风的成因。场景设想：整个地球的大气。', pts: ['三圈环流', '气压带和风带', '季风'], s: 'geo', grade: '高中', book: '选择性必修 1', issue: 79 },
  { id: 'ocean', name: '洋流和厄尔尼诺', hook: '信风一弱，半个地球的天气跟着变', desc: '世界洋流的分布规律；洋流对气候和渔场的影响；厄尔尼诺和拉尼娜。场景设想：太平洋。', pts: ['洋流的分布', '洋流的影响', '厄尔尼诺'], s: 'geo', grade: '高中', book: '选择性必修 1', issue: 80 },
  { id: 'linear', name: '一次函数', hook: '变量之间的对应', desc: '变量之间的对应；k 和 b 怎样决定一条直线。场景设想：一条公路和沿途的里程、油量。', pts: ['变量与函数', 'k 和 b', '图像与性质'], s: 'math', grade: '初中', book: '八年级下册', issue: 44 },
  { id: 'quadratic', name: '二次函数', hook: '抛物线的开口、顶点、对称轴', desc: '抛物线的开口、顶点、对称轴；用它求最值。场景设想：喷泉、投篮和一座拱桥。', pts: ['抛物线', '顶点和对称轴', '最值'], s: 'math', grade: '初中', book: '九年级上册', issue: 45 },
  { id: 'transform', name: '图形的变换', hook: '三种变换各保持了什么', desc: '三种变换各保持了什么；怎样用它们设计图案。场景设想：一间瓷砖和窗花的工坊。', pts: ['平移', '轴对称', '旋转'], s: 'math', grade: '初中', book: '七至九年级', issue: 46 },
  { id: 'similar', name: '相似和测量', hook: '相似三角形的比例', desc: '相似三角形的比例；不上去也能量出旗杆和楼的高度。场景设想：校园操场和一座塔。', pts: ['相似三角形', '测量高度', '锐角三角函数'], s: 'math', grade: '初中', book: '九年级下册', issue: 47 },
  { id: 'chance', name: '概率', hook: '随机事件', desc: '随机事件；做足够多次，频率稳定在概率附近。场景设想：一间做抽样检验的工厂。', pts: ['随机事件', '频率与概率', '用频率估计概率'], s: 'math', grade: '初中', book: '九年级上册', issue: 48 },
  { id: 'conic', name: '圆锥曲线', hook: '一刀切下去，圆锥给出三种曲线', desc: '椭圆、双曲线、抛物线是怎样切出来的；焦点和离心率；光学性质。场景设想：行星轨道和抛物面天线。', pts: ['椭圆', '双曲线和抛物线', '焦点的性质'], s: 'math', grade: '高中', book: '选择性必修第一册', issue: 81 },
  { id: 'derivative', name: '导数', hook: '这一瞬间到底有多快', desc: '平均变化率到瞬时变化率；导数的几何意义；用导数研究单调性和最值。场景设想：一条山路和一辆车。', pts: ['瞬时变化率', '切线的斜率', '单调性和最值'], s: 'math', grade: '高中', book: '选择性必修第二册', issue: 82 },
];

/** 首页用的清单。入口地址在这里补上站点的路径前缀（站点可能不在域名的根目录下） */
export const LABS: Lab[] = RAW.map(l => (l.href ? { ...l, href: import.meta.env.BASE_URL + l.href.replace(/^\//, '') } : l))
